function combinationSum3(k, n) {
  const result = [];
  const path = [];
  function backtrack(start, remaining) {
    if (path.length === k) {
      if (remaining === 0) {
        result.push([...path]);
      }
      return;
    }
    for (let digit = start; digit <= 9 && digit <= remaining; digit++) {
      path.push(digit);
      backtrack(digit + 1, remaining - digit);
      path.pop();
    }
  }
  backtrack(1, n);
  return result;
}

