function combinationSum3(k, n) {
  const out = [];
  for (let mask = 0; mask < 512; mask++) {
    const digits = [];
    for (let d = 1; d <= 9; d++) if (mask & (1 << (d - 1))) digits.push(d);
    if (digits.length === k && digits.reduce((s, d) => s + d, 0) === n) out.push(digits);
  }
  return out;
}

