function generate(rand, size) {
  const k = 2 + Math.floor(rand() * 8);
  // Aim n near the reachable range for k most of the time, but allow anything from 1 to 60.
  const low = k * (k + 1) / 2, high = k * (19 - k) / 2;
  const n = size === 'large' || rand() < 0.75 ? Math.max(1, Math.min(60, low + Math.floor(rand() * (high - low + 1)))) : 1 + Math.floor(rand() * 60);
  return [k, n];
}
